package com.bank.cachelint.lint;

// A planned operation and attributes a reviewer checks for caching mistakes.
public class OperationPlan {
    public final String name;
    public boolean cached;
    public int reuseCount;
    public boolean assumedEager;     // expects data ready right after cache()
    public boolean unpersisted;      // released after reuse?
    public boolean longRunningJob;
    public boolean usesCollect;      // pulls all data to the Driver
    public boolean expectsNoShuffleAfterCache; // wrongly thinks cache removes shuffle
    public boolean hadWideOp;        // a shuffle actually occurred

    public OperationPlan(String name) { this.name = name; }
}
