package com.bank.cachelint.lint;

import java.util.logging.Logger;

// Flags the six common caching mistakes on a planned operation.
public class CachingLinter {
    private static final Logger log = Logger.getLogger(CachingLinter.class.getName());

    public int lint(OperationPlan p) {
        int issues = 0;

        // Mistake: caching data used once.
        if (p.cached && p.reuseCount <= 1) {
            issues++;
            log.warning(() -> "'" + p.name + "': cached but reused " + p.reuseCount
                    + "x → caching single-use data wastes memory");
        }
        // Mistake: assuming cache() is eager.
        if (p.cached && p.assumedEager) {
            issues++;
            log.warning(() -> "'" + p.name + "': cache() is LAZY — first action computes+stores; "
                    + "call count() to materialize if you need it ready");
        }
        // Mistake: forgetting unpersist in long jobs.
        if (p.cached && p.longRunningJob && !p.unpersisted) {
            issues++;
            log.warning(() -> "'" + p.name + "': long job without unpersist() → caches "
                    + "accumulate until storage is exhausted");
        }
        // Mistake: confusing cache() with collect().
        if (p.usesCollect) {
            issues++;
            log.severe(() -> "'" + p.name + "': collect() pulls ALL data to the Driver "
                    + "(OOM risk) — this is NOT caching; cache() keeps data on executors");
        }
        // Mistake: thinking cache removes a shuffle.
        if (p.hadWideOp && p.expectsNoShuffleAfterCache) {
            issues++;
            log.warning(() -> "'" + p.name + "': cache does NOT remove the shuffle already done; "
                    + "it only avoids recomputing it on LATER actions");
        }
        if (issues == 0) {
            log.info(() -> "'" + p.name + "': caching usage looks correct");
        }
        return issues;
    }
}
