package com.bank.cachelint;

import com.bank.cachelint.lint.*;
import java.util.logging.*;

public class CachingLintDemo {
    private static final Logger log = Logger.getLogger(CachingLintDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new LintLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        CachingLinter linter = new CachingLinter();

        // 1) cached single-use extract + assumed eager → 2 mistakes
        OperationPlan extract = new OperationPlan("daily_extract");
        extract.cached = true; extract.reuseCount = 1; extract.assumedEager = true;
        linter.lint(extract);

        // 2) long job, cached, never unpersisted → 1 mistake
        OperationPlan cleaned = new OperationPlan("cleaned_txns");
        cleaned.cached = true; cleaned.reuseCount = 5; cleaned.longRunningJob = true;
        cleaned.unpersisted = false;
        linter.lint(cleaned);

        // 3) used collect() expecting caching → severe mistake
        OperationPlan report = new OperationPlan("big_report");
        report.usesCollect = true;
        linter.lint(report);

        // 4) thinks cache removes the groupBy shuffle → 1 mistake
        OperationPlan agg = new OperationPlan("account_totals");
        agg.cached = true; agg.reuseCount = 3; agg.hadWideOp = true;
        agg.expectsNoShuffleAfterCache = true;
        linter.lint(agg);

        // 5) correct usage → no mistakes
        OperationPlan good = new OperationPlan("ml_features");
        good.cached = true; good.reuseCount = 20; good.longRunningJob = true;
        good.unpersisted = true;
        linter.lint(good);
    }
}

